/**
 * Dream-to-Doom: Sensory Domain — Audio Engine Types
 * Defines TypeScript contracts for Tone.js audio synthesis, ambient soundscapes,
 * procedural sound effects, and game event mappings.
 */

/** Musical scale modes generated by the AI Scene Graph */
export type MusicalScaleType = 'major' | 'minor' | 'pentatonic' | 'diminished';

/** Ambient background presets supported by Tone.js synthesizer engine */
export type AmbientPresetType =
  | 'ethereal_drone'
  | 'dystopian_drone'
  | 'cyber_ambience'
  | 'nature_breeze'
  | 'volcanic_rumble'
  | 'void_silence';

/** Audio mood parameters provided by the AI Scene Graph (Zustand state) */
export interface AudioMoodConfig {
  /** Beats per minute / generative pulse speed (e.g. 120) */
  tempo: number;
  /** Musical scale determining harmonic frequencies */
  scale: MusicalScaleType;
  /** Background atmospheric synthesizer preset */
  ambientPreset: AmbientPresetType;
  /** Reverb decay duration in seconds (e.g. 2.5) */
  reverbDecay: number;
}

/** Game event triggers received from Zustand/3D world */
export type GameAudioEventType =
  | 'world_generation_started'
  | 'object_spawned'
  | 'tree_generated'
  | 'building_generated'
  | 'enemy_spawned'
  | 'object_destroyed'
  | 'environment_changed'
  | 'world_generation_completed';

/** Canonical alias for GameAudioEventType to ensure unified type safety across modules */
export type GameEventType = GameAudioEventType;

/** Metadata description for each game audio event */
export interface GameAudioEventMeta {
  type: GameAudioEventType;
  label: string;
  description: string;
  defaultPreset: string;
}

/** Web Audio context lifecycle states */
export type AudioEngineStatus =
  | 'uninitialized'
  | 'initializing'
  | 'running'
  | 'suspended'
  | 'muted'
  | 'disposed';

/** Master audio manager operational state */
export interface AudioManagerStatus {
  /** Web Audio / Tone.js context status */
  engineStatus: AudioEngineStatus;
  /** Whether master output is currently muted */
  isMuted: boolean;
  /** Master volume level normalized between 0.0 (silent) and 1.0 (max) */
  volume: number;
  /** Currently active ambient drone preset, or null if stopped */
  activeAmbientPreset: AmbientPresetType | null;
  /** True when ambient background synth is actively running */
  isAmbientPlaying: boolean;
  /** Current audio mood configuration */
  currentMood: AudioMoodConfig;
}

/** Options for playing dynamic synthesized sound effects */
export interface SoundEffectOptions {
  /** Normalized volume override (0.0 to 1.0) */
  volume?: number;
  /** Pitch transposition offset in semitones (-12 to +12) */
  pitchOffsetSemi?: number;
  /** Duration override in seconds */
  durationSec?: number;
  /** Specific note override (e.g., 'C4', 'F#5') */
  note?: string;
  /** Audio panning from -1.0 (left) to 1.0 (right) */
  pan?: number;
}

/** Master bus compression and limiter configuration */
export interface MasterAudioBusConfig {
  /** Default linear volume level (0.0 to 1.0) */
  defaultVolume: number;
  /** Minimum audible volume threshold */
  minVolume: number;
  /** Maximum allowable volume threshold */
  maxVolume: number;
  /** Decibel threshold for master limiter */
  limiterThresholdDb: number;
  /** Compression threshold in decibels */
  compressorThresholdDb: number;
  /** Compression ratio (e.g. 4:1) */
  compressorRatio: number;
  /** Crossfade ramp time in seconds when changing volume/ambient */
  fadeRampTimeSec: number;
}

/** Synth envelope parameters (ADSR: Attack, Decay, Sustain, Release) */
export interface SynthEnvelopeConfig {
  attack: number;
  decay: number;
  sustain: number;
  release: number;
}

/** Procedural sound effect definition */
export interface SoundEffectPresetConfig {
  oscillatorType: 'sine' | 'triangle' | 'sawtooth' | 'square' | 'pulse' | 'pwm';
  envelope: SynthEnvelopeConfig;
  baseNotes: string[];
  volumeDb: number;
  pitchDecay?: number;
  octaves?: number;
}

/** Ambient soundscape preset definition */
export interface AmbientPresetConfig {
  name: AmbientPresetType;
  displayName: string;
  droneNotes: string[];
  filterType: 'lowpass' | 'highpass' | 'bandpass' | 'notch';
  filterFrequency: number;
  filterQ: number;
  volumeDb: number;
  modulationSpeedHz: number;
  lfoDepth: number;
  chorusDepth: number;
}

